mapper.select:
SELECT DATE_FORMAT(`start_time`, '%Y-%m-%d') AS `date`,
       AVG(`value_num`) AS `value`,
       MIN(COALESCE(`value_min`, `value_num`)) AS `min`,
       MAX(COALESCE(`value_max`, `value_num`)) AS `max`,
       COUNT(*) AS `count`
FROM `family_health_sample`
WHERE `user_id` = #{userId}
  AND `metric` = #{metric}
  AND `start_time` >= #{from}
  AND `start_time` < #{toExclusive}
GROUP BY DATE_FORMAT(`start_time`, '%Y-%m-%d')
ORDER BY `date`
